            "(WebAssembly.validate(new Uint8Array([1]))&&WebAssembly.validate(new Uint8Array([2]))&&!WebAssembly.validate(new Uint8Array([4]),{\"builtins\":[\"js-string\"]})&&WebAssembly.validate(new Uint8Array([5])))",
